(24801, 24801, 150, 'بوابة مصر للعالم Eg-Gate', 'تأسيس ش.م.م', 'أصل خطاب من وزارة الاتصالات وتكنولوجيا المعلومات للدكتور هاني سري الدين، بشأن ترشيح السيد/ أحمد السبكي لمنصب رئيس مجلس إدارة غير تنفيذي لإدارة شركة بوابة مصر للعالم.', '23/01/2018', '2018-01-23', '1', '1', '29/01/2018', '2018-01-29', 'الشركات', 'N/A', 'محمد حمدي', NULL, NULL, 'FALSE', 0, '{\"notes\": \"\", \"lawyer\": \"محمد حمدي\", \"client_id\": \"150\", \"matter_id\": \"تأسيس ش.م.م\", \"department\": \"الشركات\", \"admin_staff\": \"N/A\", \"client_name\": \"بوابة مصر للعالم Eg-Gate\", \"document_id\": \"24801\", \"pages_count\": \"1\", \"deposit_date\": \"29/01/2018\", \"document_date\": \"23/01/2018\", \"movement_card\": \"FALSE\", \"responsible_lawyer\": \"\", \"document_description\": \"أصل خطاب من وزارة الاتصالات وتكنولوجيا المعلومات للدكتور هاني سري الدين، بشأن ترشيح السيد/ أحمد السبكي لمنصب رئيس مجلس إدارة غير تنفيذي لإدارة شركة بوابة مصر للعالم.\"}', '2025-11-23 08:02:10', '2025-11-23 08:02:44'),
(24813, 24813, 150, 'بوابة مصر للعالم Eg-Gate', 'تأسيس ش.م.م', 'أصل بطاقة حركة مستند تفيد استلام أ. مصطفى نصار لأصل خطاب من وزارة الطيران المدني للدكتور/ هاني سري الدين، بشأن قرار ترشيح السيد/ جمال محمود الجزار ممثلاً عن صندوق دعم وتطوير الطيران المدني، مرفق بالخطاب أصل قرار وزير الطيران المدني بالترشيح، وأصل إقرار قبول المرشح للتعين، وصورة بطاقة الرقم القومي للمرشح. استلمه بتاريخ 2018/02/05 لتلسيمه بالهيئة.', '23/01/2018', '2018-01-23', '1', '1', '30/01/2018', '2018-01-30', 'الشركات', 'N/A', 'محمد حمدي', NULL, 'تم تسليم المستند بالهيئة', 'FALSE', 0, '{\"notes\": \"تم تسليم المستند بالهيئة\", \"lawyer\": \"محمد حمدي\", \"client_id\": \"150\", \"matter_id\": \"تأسيس ش.م.م\", \"department\": \"الشركات\", \"admin_staff\": \"N/A\", \"client_name\": \"بوابة مصر للعالم Eg-Gate\", \"document_id\": \"24813\", \"pages_count\": \"1\", \"deposit_date\": \"30/01/2018\", \"document_date\": \"23/01/2018\", \"movement_card\": \"FALSE\", \"responsible_lawyer\": \"\", \"document_description\": \"أصل بطاقة حركة مستند تفيد استلام أ. مصطفى نصار لأصل خطاب من وزارة الطيران المدني للدكتور/ هاني سري الدين، بشأن قرار ترشيح السيد/ جمال محمود الجزار ممثلاً عن صندوق دعم وتطوير الطيران المدني، مرفق بالخطاب أصل قرار وزير الطيران المدني بالترشيح، وأصل إقرار قبول المرشح للتعين، وصورة بطاقة الرقم القومي للمرشح. استلمه بتاريخ 2018/02/05 لتلسيمه بالهيئة.\"}', '2025-11-23 08:02:10', '2025-11-23 08:02:44'),
(25341, 25341, 150, 'بوابة مصر للعالم Eg-Gate', 'تأسيس ش.م.م', 'أصل خطاب من أمين عام وزارة الطيران المدني للدكتور/ هاني سري الدين، بطلب إعادة إرسال النسخة الأصلية من اتفاق المساهمين الخاصة بصندوق دعم وتطوير الطيران المدني، مرفق به صورة ضوئية من استلام مندوب المكتب (مختار المجدلي) لأصل الخطاب المرسل من الوزارة بتاريخ 2017/10/26', '07/03/2018', '2018-03-07', '2', '2', '15/03/2018', '2018-03-15', 'الشركات', 'N/A', 'محمد حمدي', NULL, NULL, 'FALSE', 0, '{\"notes\": \"\", \"lawyer\": \"محمد حمدي\", \"client_id\": \"150\", \"matter_id\": \"تأسيس ش.م.م\", \"department\": \"الشركات\", \"admin_staff\": \"N/A\", \"client_name\": \"بوابة مصر للعالم Eg-Gate\", \"document_id\": \"25341\", \"pages_count\": \"2\", \"deposit_date\": \"15/03/2018\", \"document_date\": \"07/03/2018\", \"movement_card\": \"FALSE\", \"responsible_lawyer\": \"\", \"document_description\": \"أصل خطاب من أمين عام وزارة الطيران المدني للدكتور/ هاني سري الدين، بطلب إعادة إرسال النسخة الأصلية من اتفاق المساهمين الخاصة بصندوق دعم وتطوير الطيران المدني، مرفق به صورة ضوئية من استلام مندوب المكتب (مختار المجدلي) لأصل الخطاب المرسل من الوزارة بتاريخ 2017/10/26\"}', '2025-11-23 08:02:10', '2025-11-23 08:02:44'),
(25344, 25344, 150, 'بوابة مصر للعالم Eg-Gate', 'تأسيس ش.م.م', 'أصل مستخرج من السجل التجاري باسم \"بوابة مصر للعالم (الرقمية)\" برقم 114663، مرفق به صورة من المستخرج موقع عليها بتوقيع فورمة باستلام الأصل', '07/02/2018', '2018-02-07', '6', '6', '11/02/2018', '2018-02-11', 'الشركات', 'N/A', 'محمد حمدي', NULL, NULL, 'FALSE', 0, '{\"notes\": \"\", \"lawyer\": \"محمد حمدي\", \"client_id\": \"150\", \"matter_id\": \"تأسيس ش.م.م\", \"department\": \"الشركات\", \"admin_staff\": \"N/A\", \"client_name\": \"بوابة مصر للعالم Eg-Gate\", \"document_id\": \"25344\", \"pages_count\": \"6\", \"deposit_date\": \"11/02/2018\", \"document_date\": \"07/02/2018\", \"movement_card\": \"FALSE\", \"responsible_lawyer\": \"\", \"document_description\": \"أصل مستخرج من السجل التجاري باسم \\\"بوابة مصر للعالم (الرقمية)\\\" برقم 114663، مرفق به صورة من المستخرج موقع عليها بتوقيع فورمة باستلام الأصل\"}', '2025-11-23 08:02:10', '2025-11-23 08:02:44'),
